/**
 * An attempt to use the Java 8 streams to look up a more complicated query.
 * <p>
 * FYI, the equivalent SPARQL version (untested):
 * <pre>
 * 	SELECT ?orgName WHERE {
 * 			?org foaf:name ?orgName .
 * 			?alice foaf:member ?org .
 * 			?bob foaf:member ?org .
 * 			?alice foaf:knows ?bob .
 * 		  FILTER NOT EXIST { ?bob foaf:knows ?alice }
 *    }
 * </pre>
 *
 * @throws Exception
 */
@Test
public void whyJavaStreamsMightNotTakeOverFromSparql() throws Exception {
    Assume.assumeNotNull(bnode1, bnode2, secretClubName);
    // Find a secret organizations
    assertEquals("\"The Secret Club\"", graph.getTriples(null, knows, null).// Find One-way "knows"
    filter(t -> !graph.contains((BlankNodeOrIRI) t.getObject(), knows, t.getSubject())).map(knowsTriple -> graph.// and those they know, what are they member of?
    getTriples((BlankNodeOrIRI) knowsTriple.getObject(), member, null).// keep those which first-guy is a member of
    filter(memberTriple -> graph.contains(knowsTriple.getSubject(), member, // First hit is good enough
    memberTriple.getObject())).findFirst().get().getObject()).// then look up the name of that org
    map(org -> graph.getTriples((BlankNodeOrIRI) org, name, null).findFirst().get().getObject().ntriplesString()).findFirst().get());
}

